<script setup lang="ts">
import {ref,watch,nextTick} from 'vue'
import {useAdminUsersStore} from '@/stores/admin-users'
import type {AdminUser} from '@/api/admin-users'
const props=defineProps<{open:boolean;target:AdminUser|null}>(),emit=defineEmits<{close:[];saved:[];reload:[]}>(),store=useAdminUsersStore(),dialog=ref<HTMLDialogElement>(),reason=ref(''),localError=ref('')
watch(()=>props.target?.id,id=>{reason.value=id?store.pending[id]?.reason??'':'';localError.value='';store.commandError='';store.commandConflict=false})
watch(()=>props.open,async value=>{await nextTick();if(value&&!dialog.value?.open)dialog.value?.showModal();if(!value)dialog.value?.close()})
async function submit(){if(!props.target)return;if(!reason.value.trim()||Array.from(reason.value.trim()).length>200){localError.value='请填写1–200字的操作原因。';return}localError.value='';if(await store.submitStatus(props.target,reason.value.trim()))emit('saved')}
</script>
<template><dialog ref="dialog" class="users-dialog" aria-labelledby="admin-user-status-title" @cancel.prevent="!store.commandBusy&&emit('close')"><form @submit.prevent="submit"><header><h2 id="admin-user-status-title">{{target?.enabled?'停用账号':'恢复账号'}}</h2><button type="button" aria-label="关闭操作确认" :disabled="store.commandBusy" @click="emit('close')">×</button></header><p>{{target?.username}} · {{target?.displayName}} · ID {{target?.id}}</p><p class="users-help">{{target?.enabled?'停用后无法登录，旧会话将失效，无法保存练习、提交作答、使用AI批改、发布留言、点赞或评论。学习和留言记录保留，不自动隐藏历史内容；仍可像访客一样浏览公开页面。':'恢复后用户可重新登录继续学习，之前失效的会话不会恢复。'}}</p><label for="admin-user-reason">操作原因（必填，仅管理员可见）</label><textarea id="admin-user-reason" v-model="reason" :disabled="store.commandBusy||!!(target&&store.pending[target.id])" maxlength="400" placeholder="简要说明此次操作的原因"/><p v-if="localError||store.commandError" role="alert" class="users-error">{{localError||store.commandError}}</p><p v-if="target&&store.pending[target.id]&&!store.commandBusy" class="users-help">操作结果尚未确认，请确认原请求结果后再操作。</p><div class="users-actions"><button type="button" :disabled="store.commandBusy" @click="emit('close')">取消</button><button v-if="store.commandConflict" type="button" @click="emit('reload')">重新加载账号</button><button class="button-primary" :disabled="store.commandBusy||store.commandConflict">{{store.commandBusy?'正在处理…':target&&store.pending[target.id]?'确认操作结果':target?.enabled?'确认停用':'确认恢复'}}</button></div></form></dialog></template>
